        loader="$ProgressPreference='SilentlyContinue';$f=Join-Path $env:TEMP "+q(served_command.name)+";try{Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+served_command.name)+" -OutFile $f;if((Get-FileHash $f -Algorithm SHA256).Hash-ne "+q(command_sha)+"){throw 'Owned Trial command hash mismatch'};& ([scriptblock]::Create([IO.File]::ReadAllText($f,[Text.Encoding]::UTF8)))}finally{Remove-Item $f -ErrorAction SilentlyContinue};"
        try:result=ps(loader,timeout=55 if a.action in ('batch','headless') else 30,retry_read=a.action=='fetch')
        except Exception as failure:
            (out/(a.action+'-'+nonce+'-failure.json')).write_text(json.dumps({'phase':'UNVERIFIED_TRANSPORT_OR_ACTOR','action':a.action,'nonce':nonce,'source':a.source,'validation':a.validation,'message':str(failure),'commandSha256':hashlib.sha256(code.encode()).hexdigest(),'helper':support,'replayedInput':False},indent=2)+'\n')
            raise

        if a.action=='measure-source':
            value=json.loads(old.read_text());assert value.get('recording')==nonce
            (ROOT/'docs/replica/source'/('home-pageintegrationtrial-windows-validation-source.json' if a.validation else 'home-pageintegrationtrial-windows-parent-source.json')).write_text(json.dumps(value,indent=2,ensure_ascii=False)+'\n')
        if a.action=='headless':
            dest=m.parent/'headless-windows'/nonce;dest.mkdir(parents=True)
            records=[]
            for line in result.splitlines():
                try:v=json.loads(line)
                except json.JSONDecodeError:continue
                if 'name' in v and 'content' in v:(dest/v['name']).write_text(v['content']+'\n')
                else:records.append(v)
            (dest/'environment.json').write_text(json.dumps({'phase':'HEADLESS_RECORDED','buildManifest':str(m),'runtime':'win-x64','records':records},indent=2)+'\n')
            print('Own headless evidence:',dest)
        (out/(a.action+'-'+nonce+'.log')).write_text(result+'\n')
        if a.action=='fetch':
            for line in result.splitlines():
                v=json.loads(line);assert Path(v['name']).name==v['name'];((out/v['name']).write_bytes(base64.b64decode(v['png'])) if 'png' in v else (out/v['name']).write_text(v['content']+'\n'))
            print('Own actual evidence fetched',out)
        elif a.action!='headless':print(result)
